// Third-party code committed into the tree, which is a real pattern and not a contrived
// one: node_modules is frequently checked in, so .gitignore does not exclude it and the
// vendored rule in internal/discover/classify.go is what keeps it off the map.
//
// This exists for issue #11. `-include-vendored` read files like this one and every
// consumer downstream filtered them out again, so the flag moved the file count on stderr
// and changed nothing else. The corpus stage that covers it needs a vendored file that is
// *worth* analysing — one whose absence from the bundle is observable — which means a
// module of its own plus an import nothing in the corpus declares.
import { colorize } from 'vendored-only-tinycolor'

export function log(message: string): void {
  console.log(colorize(message))
}
